window.LOR_VERIFY = {"cv": "315_4", "checked": "22.10.2026", "pdf": "315_4_Отосклероз.pdf", "pages": 50, "items": {"m800": {"s": "ok", "sec": "1.4", "page": 10, "q": "H80.0 Отосклероз, вовлекающий овальное окно, не облитерирующий"}, "m801": {"s": "ok", "sec": "1.4", "page": 10, "q": "H80.1 Отосклероз, вовлекающий овальное окно, облитерирующий"}, "m802": {"s": "ok", "sec": "1.4", "page": 10, "q": "H80.2 Кохлеарный отосклероз"}, "m808": {"s": "ok", "sec": "1.4", "page": 10, "q": "H80.8 Другие формы отосклероза"}, "m809": {"s": "ok", "sec": "1.4", "page": 10, "q": "H80.9 Отосклероз неуточненный"}, "s1": {"s": "ok", "sec": "2", "page": 13, "q": "Критерии установления диагноза: жалобы на прогессирующее снижение слуха на одно или оба уха, субъективное ощущение шума в одном или обоих ушах; нормальная отомикроскопическая картина"}, "s2": {"s": "ok", "sec": "2.4", "page": 18, "q": "Рекомендуется выполнять всем пациентам тональную аудиометрию пороговую (ТАП) [16, 19, 30, 31, 33, 34, 39, 60] для оценки формы и степени тугоухости. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4) Комментарии: наибольшее распространение в диагностике отосклероза получила ТАП. Оценивают не только уровень слуха по ВП и КП, но и величину КВИ (резерв улитки). Для отосклероза характерно двустороннее повышение порогов по ВП в зоне низких и средних частот (0,125-2 кГц), чаще в виде восходящей кривой с небольшим подъемом"}, "s3": {"s": "ok", "sec": "2.4", "page": 19, "q": "Рекомендуется всем пациентам проведение акустической импедансометрии (тимпанометрия и акустическая рефлексометрия) для исключения патологии среднего уха, определения давления в среднем ухе, оценке вентиляционной функции слуховой трубы, степени подвижности барабанной перепонки, функционального состояния цепи слуховых косточек [31]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: для отосклероза характерна тимпанограмма типа «А» или «As» и отсутствие акустического рефлекса"}, "s4": {"s": "ok", "sec": "3.2", "page": 25, "q": "Рекомендована стапедопластика пациентам старше 15 лет с отосклерозом при кондуктивный или смешанный характер тугоухости с КВИ - не менее 25-30 дБ; отсутствие признаков активного отосклероза (по данным отомикроскопии и КТ височных костей с денситометрией); отсутствие общих противопоказаний для проведения планового хирургического вмешательства [19, 31, 33, 34, 39, 54] (см. Приложение Г2) Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "s5": {"s": "ok", "sec": "3.1", "page": 23, "q": "Рекомендуется инактивирующая терапия взрослым пациентам: - с кохлеарной формой отосклероза, с целью инактивации очагов отоспонгиоза [35]; - с тимпанальной и смешанной формами отосклероза в активной стадии на дооперационном этапе, с целью инактивации очагов отоспонгиоза [29]; - с активной формой, выявленной во время хирургического лечения, с целью инактивации очагов отоспонгиоза [29]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "s6": {"s": "ok", "sec": "3.3", "page": 25, "q": "Рекомендуется проведение электроакустической реабилитации всем пациентам с недостаточным уровнем слуха и разборчивости речи в том числе и после хирургического лечения, кохлеарной форме отосклероза, при общих противопоказаниях для хирургического лечения, отказе пациента от хирургического лечения [57]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "c-def": {"s": "ok", "sec": "1.1", "page": 6, "q": "Отосклероз – специфическое заболевание, представляющее собой первичное метаболическое поражение костной капсулы ушного лабиринта, выражающееся особой формой остеодистрофии с преимущественно двусторонним очаговым поражением энхондрального слоя капсулы. При этом вначале наблюдается деструкция костной ткани с образованием мягких отоспонгиозных кровенаполненных очагов, а затем – образование очень плотной склеротической кости вследствие отложения в этих очагах солей кальция. Эти фазы размягчения и склерозирования кости имеют волнообразное течение."}, "c-etio": {"s": "ok", "sec": "1.2", "page": 7, "q": "Многочисленные генетические исследования доказывают, что отосклероз является аутосомнодоминантным заболеванием с проявляемостью гена от 20 до 40%, или неполной его проявляемостью."}, "c-class": {"s": "ok", "sec": "1.5", "page": 11, "q": "Наиболее распространенной в России является классификация отосклероза, разработанная Н.А. Преображенским и О.К. Патякиной в 1973 году [21]. Она основана на данных ТПА, с учетом состояния усредненных значений порогов КП на частотах 0,5, 1 и 2 кГц."}, "cl-tymp": {"s": "ok", "sec": "1.5", "page": 11, "q": "Тимпанальная форма (пороги слуха по КП до 20)"}, "cl-m1": {"s": "ok", "sec": "1.5", "page": 11, "q": "смешанная форма I (от 21 до 30 дБ)"}, "cl-m2": {"s": "ok", "sec": "1.5", "page": 11, "q": "смешанная форма II (>30 дБ)"}, "cl-coch": {"s": "ok", "sec": "1.5", "page": 11, "q": "кохлеарная форма (КП >50 дБ)."}, "w-class": {"s": "ok", "sec": "1.5", "page": 11, "q": "В зависимости от уровня средних порогов КП выделяют: тимпанальную, смешанную I, смешанную II и кохлеарную формы отосклероза. Тимпанальная форма (пороги слуха по КП до 20); смешанная форма I (от 21 до 30 дБ); смешанная форма II (>30 дБ) и кохлеарная форма (КП >50 дБ)."}, "c-stage": {"s": "ok", "sec": "1.5", "page": 11, "q": "Согласно многим патоморфологическим и клиническим исследованиям, принято выделять гистологический и клинический отосклероз, активную (незрелую, отоспонгиоз) и неактивную (зрелую) его стадии, что во многом определяет характер лечения пациента [22]."}, "c-ct": {"s": "ok", "sec": "1.5", "page": 11, "q": "По распространенности очагов отосклероза, выявленной при проведении МСКТ височных костей с МПР выделяют фенестральную, ретрофенестральную и смешанную формы [25, 26]. Фенестральная форма характеризуется локализацией очагов отосклероза в области окна преддверия капсулы лабиринта, ретрофенестральная – вокруг базального и апикального завитков, у окна улитки, полукружных каналов и дна ВСП, и смешанная – их комбинацией. Очаги могут быть единичными или множественными. Одной из характеристик метода МСКТ височных костей является денситометрия, которая используется для анализа плотности капсулы лабиринта. Установлено, что при плотности менее 1000 ед. НU (плотность нормальной костной капсулы лабиринта +2000 – +2200 ед. НU – единицы Hounsfield) отосклеротический процесс является активным (деминерализация, отоспонгиоз); при плотности более 1000 ед. НU – неактивным [27, 28]."}, "c-intraop": {"s": "ok", "sec": "1.5", "page": 11, "q": "Другие классификации основаны на интраоперационной визуализации распространённости очагов отосклероза. В связи с тем, что во время хирургического вмешательства возможна лишь визуальная оценка распространённости процесса в НОП. Ряд авторов выявляет только 4 типа стапедиального отосклероза: ограниченный, умеренный, распространенный и облитерирующий [16, 23]. Наиболее сложными для проведения стапедопластики являются облитерирующие формы отосклероза. По визуальной картине их разделяют на 3 степени: 1 – утолщение ППС за счет равномерного распространения отоочагов; 2 – отоочаги суживают НОП по краям, при этом ППС не изменена; 3 – очаги отосклероза суживают нишу, вовлекая в процесс и ППС и суперструктуры стремени [24]."}, "c-clin": {"s": "ok", "sec": "1.6", "page": 12, "q": "Основными симптомами отосклеротического поражения капсулы лабиринта являются: прогрессирующее, чаще двустороннее снижение слуха и субъективное ощущение шума в одном или обоих ушах низко- и среднечастотного характера (у 50%), реже пациенты отмечают высокочастотный шум (у 10%) [19, 21, 30, 31]. Иногда отмечается относительно лучшее восприятие речи в условиях шума, чем в тишине - paracusis Willisii (Виллизия симптом, Виллизия феномен, паракузия). Симптом обнаруживают в среднем у половины пациентов с отосклерозом [31]. Жалобы на головокружение и расстройство равновесия предъявляют лишь 24% больных отосклерозом [31]."}, "d-crit": {"s": "ok", "sec": "2", "page": 13, "q": "Критерии установления диагноза: жалобы на прогессирующее снижение слуха на одно или оба уха, субъективное ощущение шума в одном или обоих ушах; нормальная отомикроскопическая картина; кондуктивная, смешанная или нейросесорная тугоухость по данным тональной аудиометрии пороговой, с 100% разборчивость речи по данным речевой аудиометрии; по данным акустической импедансометрии определяется тип «А» или «Аs» тимпанограммы и отсутствие акустических рефлексов"}, "d-crit-2": {"s": "ok", "sec": "2", "page": 13, "q": "латерализация ултразвука (УЗВ) при кохлеарном отосклерозе направлена в лучше слышащее ухо, при одностороннем или асимметричном двустороннем снижении слуха, пороги чувствительности УЗВ в пределах нормы или несколько выше, при фенестральной или смешанных формах - в хуже слышащее ухо и пороги чувствительности УЗВ соответствуют до 15 дБ; по данным компьютерной томографии височных костей с денситометрией определяется наличие участков пониженной плотности на фоне высокоплотной гомогенной капсулы лабиринта. При фенестральной форме по данным компьютерной томографии височной кости в промонториальной стенке барабанной полости, кпереди от окна преддверия определяется очаг, плотность которого ниже плотности капсулы лабиринта – очаг отоспонгиоза (отосклероза); при кохлеарной форме - очаги пониженной плотности в капсуле лабиринта, повторяющие ход завитков улитки, достигающие стенок внутреннего слухового прохода"}, "w-crit": {"s": "ok", "sec": "2", "page": 13, "q": "при смешанной форме - признаки характерные, как для фенестральной, так и смешанной форм отосклероза."}, "d-hl": {"s": "ok", "sec": "2.1", "page": 14, "q": "Рекомендуется опрашивать всех пациентов о прогрессирующем снижении слуха на одно или оба уха [19, 21, 30, 31]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: основными жалобами пациентов при всех формах отосклероза являются прогрессирующее, постепенное, «беспричинное» снижение слуха. Тугоухость при отосклерозе, как правило, двусторонняя, в 15-30% случаев определяется односторонний процесс. На течение заболевания и характера тугоухости влияет активность отосклеротических очагов. Так отмечено, что ранний возраст начала снижения слуха характеризуется формированием облитерирующих и распространенных очагов отосклероза, а поздний возраст – ограниченных очагов. Появление очагов в раннем возрасте вызывает быстрое прогрессирование тугоухости, чего не наблюдается в пожилом возрасте [16, 32]."}, "d-hl-c": {"s": "ok", "sec": "2.1", "page": 14, "q": "основными жалобами пациентов при всех формах отосклероза являются прогрессирующее, постепенное, «беспричинное» снижение слуха. Тугоухость при отосклерозе, как правило, двусторонняя, в 15-30% случаев определяется односторонний процесс. На течение заболевания и характера тугоухости влияет активность отосклеротических очагов. Так отмечено, что ранний возраст начала снижения слуха характеризуется формированием облитерирующих и распространенных очагов отосклероза, а поздний возраст – ограниченных очагов. Появление очагов в раннем возрасте вызывает быстрое прогрессирование тугоухости, чего не наблюдается в пожилом возрасте"}, "d-noise": {"s": "ok", "sec": "2.1", "page": 14, "q": "Рекомендуется опрашивать всех пациентов о наличии ушного шума в одном или обоих ушах [19, 33, 34]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "d-noise-c": {"s": "ok", "sec": "2.1", "page": 14, "q": "довольно постоянным признаком отосклеротического поражения является субъективное ощущение шума в одном или обоих ушах низко- и среднечастотного характера (у 50%), реже пациенты отмечают высокочастотный шум (у 10%). В начале заболевания шум слышен только в тишине, с нарастанием уровня тугоухости его интенсивность увеличивается"}, "d-par": {"s": "ok", "sec": "2.1", "page": 14, "q": "Рекомендуется опрашивать всех пациентов об улучшении слуха в шумной обстановке [30]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "d-par-c": {"s": "ok", "sec": "2.1", "page": 14, "q": "характерный признак отосклероза – относительно лучшее восприятие речи в условиях шума, чем в тишине – paracusis Willisii (Виллизия симптом, Виллизия феномен, паракузия). Симптом обнаруживают в среднем у половины пациентов с отосклерозом, он более характерен для выраженной фиксации стремени, если остается сохранным уровень костного звукопроведения. С развитием смешанной формы тугоухости"}, "d-vert": {"s": "ok", "sec": "2.1", "page": 14, "q": "Рекомендуется опрашивать всех пациентов о наличии головокружения и/или расстройств равновесия [36, 37]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 4)"}, "d-vert-c": {"s": "ok", "sec": "2.1", "page": 14, "q": "жалобы на головокружение и расстройство равновесия предъявляют около 24% пациентов с отосклерозом. Среди пациентов с головокружениями у 0,7% выявлен  отосклероз [36]. Объясняются данные вестибулярные расстройства внутрилабиринтной гипертензией, поскольку после операции эти расстройства купируются."}, "d-micro": {"s": "ok", "sec": "2.2", "page": 16, "q": "Рекомендуется выполнять всем пациентам отомикроскопию и/или отоэндоскопию для оценки состояния наружного слухового прохода и барабанной перепонки [19, 31, 33, 34, 35, 38]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "d-micro-c": {"s": "ok", "sec": "2.2", "page": 16, "q": "при отомикроскопии барабанная перепонка состоятельная с четкими опознавательными контурами. Можно визуализировать характерные признаки отосклероза, однако они выявляются у 10-21% пациентов"}, "d-signs": {"s": "ok", "sec": "2.2", "page": 16, "q": "К ним относят симптом Лемперта (истончение барабанной перепонки с изменением ее цвета, обусловленное атрофией фиброзного слоя), симптом Хилова (истончение кожи наружного слухового прохода), симптом Тойнби (отсутствие или уменьшение количества серы в наружном слуховом проходе). Cимптом Швартца (просвечивание расширенных сосудов слизистой оболочки в области мыса через истонченную барабанную перепонку – признак активной стадии отосклероза), выявляется у 50% пациентов. Cимптом Вирховского-Тилло (уменьшение чувствительности кожи наружного слухового прохода, барабанной перепонки и секреции потовых желез, широкий наружный слуховой проход). Однако, ни один из отоскопических признаков отосклероза нельзя назвать патогномоничным, их принимают во внимание только в комплексе с другими проявлениями болезни"}, "d-lab": {"s": "ok", "sec": "2.3", "page": 17, "q": "Специфической лабораторной диагностики не существует. Лабораторные методы исследования выполняются при подготовке к плановой госпитализации (плановое хирургическое лечение)"}, "d-fork": {"s": "ok", "sec": "2.4", "page": 18, "q": "Рекомендуется выполнять камертональные исследования всем пациентам: пробы Ринне, Федериче, Вебера для скрининговой оценки характера тугохости [16, 19, 30, 31, 33, 34, 35, 60]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "d-fork-c": {"s": "ok", "sec": "2.4", "page": 18, "q": "камертональные качественные исследования (С128-512) позволяют в скрининговом режиме определить (пробы Ринне и Федеричи) наличие костно-воздушного интервала (КВИ) и хуже слышащее ухо (проба Вебера), которые служат показанием к назначению ТПА. При кохлеарной форме отосклероза отмечаются положительные камертональные пробы Ринне и Федеричи, а латерализация звука камертонов С128-512 при проведении пробы Вебера – в лучше слышащее ухо."}, "d-tpa": {"s": "ok", "sec": "2.4", "page": 18, "q": "Рекомендуется выполнять всем пациентам тональную аудиометрию пороговую (ТАП) [16, 19, 30, 31, 33, 34, 39, 60] для оценки формы и степени тугоухости. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "d-tpa-c": {"s": "ok", "sec": "2.4", "page": 18, "q": "наибольшее распространение в диагностике отосклероза получила ТАП. Оценивают не только уровень слуха по ВП и КП, но и величину КВИ (резерв улитки). Для отосклероза характерно двустороннее повышение порогов по ВП в зоне низких и средних частот (0,125-2 кГц), чаще в виде восходящей кривой с небольшим подъемом. С развитием и увеличением длительности болезни отмечается повышение порогов КП. Что касается повышения порогов слуха по КП, то данные изменения объясняются как поражением звукопроводящего аппарата, так и нарушением внутриулиткового проведения [30]. Именно нарушением микромеханики и гидродинамики улитки на частотах 0,5-2 кГц объясняется теория R. Carhartа о механической природе сенсоневрального компонента при отосклерозе [30,39]. В зависимости от характера аудиометрической кривой различают тимпанальную, смешанную и кохлеарную формы отосклероза"}, "d-speech": {"s": "ok", "sec": "2.4", "page": 19, "q": "При речевой аудиометрии в зависимости от выраженности тугоухости отмечается 100% разборчивость речи [31]."}, "d-uzv": {"s": "ok", "sec": "2.4", "page": 18, "q": "Рекомендуется проведение всем пациентам исследование чувствительности к ультразвуку и его латерализации для оценки характера тугоухости [30, 31, 60]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "d-uzv-c": {"s": "ok", "sec": "2.4", "page": 18, "q": "при анализе результатов УЗВ аудиометрии выявлено, что для больных отосклерозом пороги чувствительности УЗВ соответствуют до 15 дБ. При кохлеарной форме они в пределах нормы или несколько выше. Латерализация УЗВ при кохлеарном отосклерозе направлена в лучше слышащее ухо при одностороннем или асимметричном двустороннем снижении слуха [35, 40]. Если при отосклерозе латерализация УЗВ направлена в хуже слышащее ухо (определяется в 60,9% случаев), то это может свидетельствовать, в том числе, и о наличии гидропса лабиринта вследствие нарушения гидродинамики. Это характерно для больных, страдающих отосклерозом более 10 лет, и подтверждается данными ЭКоГ [19]."}, "d-hydrops": {"s": "ok", "sec": "2.4", "page": 19, "q": "Также имеются данные о том, что очаги отосклероза могут вовлекать в процесс утрикулярный нерв и сдавливать эндолимфатический проток [19, 33, 35]. Выраженная обструкция дистального отдела эндолимфатического протока очагами отосклероза может вызвать и расширение саккулюса, вплоть до его соприкосновения с основанием стремени [36]. В то же время ни одна из методик достоверно не свидетельствует о 100% диагностике гидропса лабиринта, его локализации в эндо- или перилимфатическом пространстве, что является важным для определения показаний к операции и ее результата [41]."}, "d-imp": {"s": "ok", "sec": "2.4", "page": 19, "q": "Рекомендуется всем пациентам проведение акустической импедансометрии (тимпанометрия и акустическая рефлексометрия) для исключения патологии среднего уха, определения давления в среднем ухе, оценке вентиляционной функции слуховой трубы, степени подвижности барабанной перепонки, функционального состояния цепи слуховых косточек [31]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "d-imp-c": {"s": "ok", "sec": "2.4", "page": 19, "q": "для отосклероза характерна тимпанограмма типа «А» или «As» и отсутствие акустического рефлекса (Приложение Г1)."}, "d-imp-def": {"s": "ok", "sec": "Термины и определения", "page": 4, "q": "Акустическая импедансометрия – это комплексный метод исследования заболеваний органа слуха. Включает в себя тимпанометрию, определение акустического импеданса (сопротивления) и акустического миорефлекса."}, "alg-tpa": {"s": "ok", "sec": "Приложение А3", "page": 42, "q": "Алгоритм обследования Формы отосклероза (классификация Н.А. Преображенского и О.К. Патякиной – 1973 г.) тимпанальная смешанная кохлеарная Тональная аудиометрия: - вид аудиометрической кривой; - пороги по КП (0,5-2 кГц); - КВИ горизонтальный до 20 дБ 30-50 дБ пологонисходящий до 50 дБ 30 Дб крутонисходящий свыше 50 дБ менее 10 дБ", "note": "Сверено по изображению страницы 42.", "img": [42]}, "alg-speech": {"s": "ok", "sec": "Приложение А3", "page": 42, "q": "Алгоритм обследования Формы отосклероза (классификация Н.А. Преображенского и О.К. Патякиной – 1973 г.) тимпанальная смешанная кохлеарная Тональная аудиометрия: - вид аудиометрической кривой; - пороги по КП (0,5-2 кГц); - КВИ горизонтальный до 20 дБ 30-50 дБ пологонисходящий до 50 дБ 30 Дб крутонисходящий свыше 50 дБ менее 10 дБ Разборчивость речи 100% 100% 100%", "note": "Сверено по изображению страницы 42.", "img": [42]}, "alg-uzv": {"s": "ok", "sec": "Приложение А3", "page": 42, "q": "Алгоритм обследования Формы отосклероза (классификация Н.А. Преображенского и О.К. Патякиной – 1973 г.) тимпанальная смешанная кохлеарная Тональная аудиометрия: - вид аудиометрической кривой; - пороги по КП (0,5-2 кГц); - КВИ горизонтальный до 20 дБ 30-50 дБ пологонисходящий до 50 дБ 30 Дб крутонисходящий свыше 50 дБ менее 10 дБ Разборчивость речи 100% 100% 100% Пороги чувствительности к УЗВ 10 вт 10-15 вт >15 вт", "note": "Сверено по изображению страницы 42.", "img": [42]}, "alg-fung": {"s": "ok", "sec": "Приложение А3", "page": 42, "q": "Алгоритм обследования Формы отосклероза (классификация Н.А. Преображенского и О.К. Патякиной – 1973 г.) тимпанальная смешанная кохлеарная Тональная аудиометрия: - вид аудиометрической кривой; - пороги по КП (0,5-2 кГц); - КВИ горизонтальный до 20 дБ 30-50 дБ пологонисходящий до 50 дБ 30 Дб крутонисходящий свыше 50 дБ менее 10 дБ Разборчивость речи 100% 100% 100% Пороги чувствительности к УЗВ 10 вт 10-15 вт >15 вт Наличие ФУНГа Нет Редко Часто", "note": "Сверено по изображению страницы 42.", "img": [42]}, "alg-tymp": {"s": "ok", "sec": "Приложение А3", "page": 42, "q": "Алгоритм обследования Формы отосклероза (классификация Н.А. Преображенского и О.К. Патякиной – 1973 г.) тимпанальная смешанная кохлеарная Тональная аудиометрия: - вид аудиометрической кривой; - пороги по КП (0,5-2 кГц); - КВИ горизонтальный до 20 дБ 30-50 дБ пологонисходящий до 50 дБ 30 Дб крутонисходящий свыше 50 дБ менее 10 дБ Разборчивость речи 100% 100% 100% Пороги чувствительности к УЗВ 10 вт 10-15 вт >15 вт Наличие ФУНГа Нет Редко Часто Тимпанометрия Тип А Тип А Тип А", "note": "Сверено по изображению страницы 42.", "img": [42]}, "alg-ct": {"s": "ok", "sec": "Приложение А3", "page": 42, "q": "Алгоритм обследования Формы отосклероза (классификация Н.А. Преображенского и О.К. Патякиной – 1973 г.) тимпанальная смешанная кохлеарная Тональная аудиометрия: - вид аудиометрической кривой; - пороги по КП (0,5-2 кГц); - КВИ горизонтальный до 20 дБ 30-50 дБ пологонисходящий до 50 дБ 30 Дб крутонисходящий свыше 50 дБ менее 10 дБ Разборчивость речи 100% 100% 100% Пороги чувствительности к УЗВ 10 вт 10-15 вт >15 вт Наличие ФУНГа Нет Редко Часто Тимпанометрия Тип А Тип А Тип А МСКТ височных костей фенестральная локализация очагов Методики стапедопластики фенестральная и локализация очагов улитковая часто деминерализация улитки", "note": "Сверено по изображению страницы 42.", "img": [42]}, "w-alg": {"s": "ok", "sec": "Приложение А3", "page": 42, "q": "Алгоритм обследования Формы отосклероза (классификация Н.А. Преображенского и О.К. Патякиной – 1973 г.) тимпанальная смешанная кохлеарная Тональная аудиометрия: - вид аудиометрической кривой; - пороги по КП (0,5-2 кГц); - КВИ горизонтальный до 20 дБ 30-50 дБ пологонисходящий до 50 дБ 30 Дб крутонисходящий свыше 50 дБ менее 10 дБ Разборчивость речи 100% 100% 100% Пороги чувствительности к УЗВ 10 вт 10-15 вт >15 вт Наличие ФУНГа Нет Редко Часто Тимпанометрия Тип А Тип А Тип А МСКТ височных костей фенестральная локализация очагов Методики стапедопластики фенестральная и локализация очагов улитковая часто деминерализация улитки", "note": "Сверено по изображению страницы 42.", "img": [42]}, "d-ct": {"s": "ok", "sec": "2.4", "page": 19, "q": "Рекомендуется всем пациентам компьютерная томография височных костей для определения отосклероза, локализации, распространенности и оценки степени активности очагов [19, 29, 30, 31, 33, 35, 39, 60]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 4)"}, "d-ct-c": {"s": "ok", "sec": "2.4", "page": 19, "q": "в настоящее время МСКТ височных костей (шагом 0,3-1 мм) в аксиальной и коронарной проекциях с МПР и денситометрией является единственным объективным, неинвазивным методом определения отосклероза, его локализации, распространённости и оценки степени активности очагов (чувствительность метода 80-95%, специфика – 99,1%)"}, "d-ct-diff": {"s": "ok", "sec": "2.4", "page": 19, "q": "МСКТ височных костей до операции играет большую роль в диагностике анатомических особенностей строения, аномалий и заболеваний височной кости, симулирующих отосклеротическую тугоухость и снижающих эффективность хирургического лечения: неотосклеротическая фиксация цепи слуховых косточек, дегисценция ВПК, расширение водопровода преддверия, остеодистрофии (синдром Ван-дер-Хуве), облитерирующий отосклероз, оссификация окна улитки и лабиринта. Все это в значительной степени влияет на планирование хирургического лечения и его прогноз [43,50, 51, 52]."}, "d-ct-dens": {"s": "ok", "sec": "2.4", "page": 19, "q": "Снижение плотности капсулы  лабиринта от +1500 до +300 ед. НU (в норме +2000 – +2200 ед. НU) свидетельствует о начальной или далеко зашедшей ее деминерализации"}, "d-ct-fen": {"s": "ok", "sec": "2.4", "page": 20, "q": "При фенестральной форме отосклероза, на МСКТ височных костей, очаги отосклероза наиболее часто визуализируются в области впередиоконной щели, переднего полюса основания стремени, распространяющиеся на переднюю его ножку. Плотность зрелых очагов отосклероза в основном составляет от +1000 до +1100 ед HU. При плотности очагов от +500 до +800 ед. HU, можно предположить наличие активного отосклероза (отоспонгиоза) (рис. 1). Стоит отметить, что при фенестральной локализации очагов отосклероза по данным МСКТ височных костей, вид тугоухости может быть различным (от тимпанальной до смешанной формы)"}, "d-ct-mix": {"s": "ok", "sec": "2.4", "page": 20, "q": "При смешанных формах, выявленных по МСКТ височных костей, помимо фенестральной локализации очагов отоспонгиоза или отосклероза, определяются участки пониженной плотности капсулы лабиринта, окружающие улитку, распространяющиеся на область окна улитки, иногда до дна ВСП (рис. 2). При этом по данным ТПА может определяться смешанная форма тугоухости (1-2 ст.)"}, "d-ct-coch": {"s": "ok", "sec": "2.4", "page": 21, "q": "При кохлеарном отосклерозе, в начальной его стадии в костной капсуле лабиринта, окружающей улитку, выявляются участки пониженной плотности +1500 – +1100 ед. HU. При умеренно выраженной активной стадии – в костной капсуле лабиринта, вокруг базального и апикального завитков улитки определяются хорошо видимые на томограммах участки пониженной плотности +1000 – +600 ед. HU, часто распространяющиеся на область окна улитки и могут достигать дна ВСП и горизонтального полукружного канала (рис. 3)."}, "d-ct-coch2": {"s": "ok", "sec": "2.4", "page": 21, "q": "На стадии высокой активности кохлеарного отосклероза выявляется деминерализация костной капсулы ушного лабиринта на уровне базального и апикального завитков улитки. Также изменения могут достигать преддверия и полукружных каналов. Плотность при этом колеблется от +300 до +600 ед. HU. На этой стадии развития отосклероза могут определяться явления костной облитерации структур лабиринта. Наиболее часто явления облитерации по данным МСКТ височных костей выявляются в базальном завитке улитке и горизонтальном полукружном канале"}, "w-hu": {"s": "ok", "sec": "2.4", "page": 20, "q": "Плотность зрелых очагов отосклероза в основном составляет от +1000 до +1100 ед HU. При плотности очагов от +500 до +800 ед. HU, можно предположить наличие активного отосклероза (отоспонгиоза) (рис. 1). Стоит отметить, что при фенестральной локализации очагов отосклероза по данным МСКТ височных костей, вид тугоухости может быть различным (от тимпанальной до смешанной формы) [30, 31,45,53]. Рис. 1. Активная форма отосклероза (отоспонгиоз): плотность очагов +300 – +800 ед. НU. При смешанных формах, выявленных по МСКТ височных костей, помимо фенестральной локализации очагов отоспонгиоза или отосклероза, определяются участки пониженной плотности капсулы лабиринта, окружающие улитку, распространяющиеся на область окна улитки, иногда до дна ВСП (рис. 2). При этом по данным ТПА может определяться смешанная форма тугоухости (1-2 ст.) [30, 31, 45, 53]. Рис. 2. Смешанная форма отосклероза (плотность очагов отоспонгиоза +300 – +800 ед. НU).  При кохлеарном отосклерозе, в начальной его стадии в костной капсуле лабиринта, окружающей улитку, выявляются участки пониженной плотности +1500 – +1100 ед. HU. При умеренно выраженной активной стадии – в костной капсуле лабиринта, вокруг базального и апикального завитков улитки определяются хорошо видимые на томограммах участки пониженной плотности +1000 – +600 ед. HU, часто распространяющиеся на область окна улитки и могут достигать дна ВСП и горизонтального полукружного канала (рис. 3). Рис. 3. Кохлеарная форма отосклероза (плотность очагов +600 – +800 ед. НU)"}, "d-ct-postop": {"s": "ok", "sec": "2.4", "page": 21, "q": "Также МСКТ височных костей актуальна для диагностики причин неудовлетворительных результатов стапедопластики. С помощью метода можно определить положение протеза, глубину его погружения в преддверие, некроз длинной ножки наковальни, перилимфатическую фистулу и гранулему окна преддверия."}, "t-inact": {"s": "ok", "sec": "3.1", "page": 23, "q": "Рекомендуется инактивирующая терапия взрослым пациентам: - с кохлеарной формой отосклероза, с целью инактивации очагов отоспонгиоза [35]; - с тимпанальной и смешанной формами отосклероза в активной стадии на дооперационном этапе, с целью инактивации очагов отоспонгиоза [29]; - с активной формой, выявленной во время хирургического лечения, с целью инактивации очагов отоспонгиоза [29]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "t-inact-c": {"s": "ok", "sec": "3.1", "page": 23, "q": "инактивирующая терапия вследствие ослабления ферментативных процессов снижает активность отосклероза, тормозит нарастание сенсоневрального компонента тугоухости, увеличивает плотность капсулы лабиринта и уменьшает вероятность реоссификации после операции. Кроме того, данная терапия останавливает рост отоспонгиозных очагов и препятствует облитерации улитки [54]."}, "t-inact-ct": {"s": "ok", "sec": "3.1", "page": 23, "q": "Взрослым пациентам с различными формами активного отосклероза проводят курсы инактивирующей терапии с помощью комплекса лекарственных средств с учетом плотности очагов отоспонгиоза в лабиринте по данным МСКТ височных костей с денситометрическим исследованием [29]. Комплекс инактивирующей терапии включает (1 курс): 1. Бифосфонат [31]– препарат (#Ибандроновая кислота"}, "dr-iban": {"s": "ok", "sec": "3.1", "page": 23, "q": "Бифосфонат [31]– препарат (#Ибандроновая кислота - высокоактивный азотсодержащий бифосфонат, ингибитор костной резорбции и активности остеокластов), применяется у взрослых пациентов парентерально в виде раствора однократно, внутривенно, болюсно (в течение 15-30 сек в дозе 3 мг/3 мл) в условиях процедурного кабинета, 1 раз в 3 месяца; или внутрь в таблетках по 150 мг 1 раз в месяц за 1 час до еды, запивая стаканом воды [29]."}, "dr-alen": {"s": "ok", "sec": "3.1", "page": 23, "q": "Или препарат алендроновой кислоты (#Алендроновая кислота** ) - по 1 таблетке (70 мг) 1 раз в неделю за 1 час до еды, запивая стаканом воды [55]."}, "dr-ca": {"s": "ok", "sec": "3.1", "page": 24, "q": "#Кальция глюконат 500 мг применяется у взрослых пациентов по 1 таблетке 3 раза в день после еды [29]."}, "dr-naf": {"s": "ok", "sec": "3.1", "page": 24, "q": "#Натрия фторид применяется у взрослых пациентов в таблетках по 30-60 мг (0,5 мг / 1 кг массы)в течении 2 месяцев"}, "dr-alfa": {"s": "ok", "sec": "3.1", "page": 24, "q": "#Альфакальцидол** – применяется у взрослых пациентов по 1 капсуле (0,25 мкг) 1 раз в день"}, "t-course": {"s": "ok", "sec": "3.1", "page": 24, "q": "Предложенный комплекс препаратофективен курсом в течение 3 месяцев. При этом количество курсов 1, 2 или 4 с перерывом в 3 месяца зависит от плотности очагов отоспонгиоза в лабиринте, которая определяется методом МСКТ височных костей с денситометрией. Курсы инактивирующей терапии проводятся до момента достижения плотности очагов не менее +1000 –+1500 ед. HU."}, "crs-300": {"s": "ok", "sec": "3.1", "page": 24, "q": "при плотности очагов отоспонгиоза <+300 ед. HU назначается 4 курса комплексной инактивирующей терапии"}, "crs-600": {"s": "ok", "sec": "3.1", "page": 24, "q": "при +300 – +600 ед. HU – 2 курса"}, "crs-900": {"s": "ok", "sec": "3.1", "page": 24, "q": "при +600 – +900 ед. HU – 1 курс"}, "w-course": {"s": "ok", "sec": "1.5, 3.1", "page": 24, "q": "при плотности очагов отоспонгиоза <+300 ед. HU назначается 4 курса комплексной инактивирующей терапии, - при +300 – +600 ед. HU – 2 курса, при +600 – +900 ед. HU – 1 курс", "note": "Граница активности (1000 HU) — в разделе 1.5."}, "t-ind": {"s": "ok", "sec": "3.2", "page": 24, "q": "Показаниями к хирургическому лечению являются: 1. жалобы пациента на снижение слуха и наличие субъективного ушного шума; 2. кондуктивный или смешанный характер тугоухости с КВИ – не менее 30 дБ; 3. отсутствие признаков активного отосклероза (по данным отомикроскопии и МСКТ височных костей с денситометрией); 4. отсутствие перфорации барабанной перепонки и инфекции в наружном слуховом проходе; 5. отсутствие общих противопоказаний для проведения планового хирургического вмешательства."}, "t-stapes": {"s": "ok", "sec": "3.2", "page": 25, "q": "Рекомендована стапедопластика пациентам старше 15 лет с отосклерозом при кондуктивный или смешанный характер тугоухости с КВИ - не менее 25-30 дБ; отсутствие признаков активного отосклероза (по данным отомикроскопии и КТ височных костей с денситометрией); отсутствие общих противопоказаний для проведения планового хирургического вмешательства [19, 31, 33, 34, 39, 54] (см. Приложение Г2) Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "t-stapes-c": {"s": "ok", "sec": "3.2", "page": 25, "q": "стапедопластика является паллиативным хирургическим методом лечения кондуктивной и смешанной тугоухости у пациентов с отосклерозом. В пользу проведения операции свидетельствует факт большего прогрессирования нейросенсорного компонента тугоухости в неоперированных ушах в сравнении с оперированными [16, 39, 40]."}, "t-stapes-ci": {"s": "ok", "sec": "3.2", "page": 25, "q": "Хирургическое вмешательство противопоказано во время острых и обострения хронических воспалительных процессов, а также в период декомпенсации существующих у пациента заболеваний. Относительными противопоказаниями для выполнения стапедопластики являются активный отосклеротический процесс, операция на единственно слышащем ухе и наличие широкого водопровода преддверия по данным МСКТ височных костей. В зарубежной литературе имеются сведения развития послеоперационной глухоты у пациентов с отосклерозом и синдромом широкого водопровода преддверия."}, "w-kvi": {"s": "ok", "sec": "3.2, 6", "page": 24, "q": "2. кондуктивный или смешанный характер тугоухости с КВИ – не менее 30 дБ; 3. отсутствие признаков активного отосклероза (по данным отомикроскопии и МСКТ височных костей с денситометрией); 4. отсутствие перфорации барабанной перепонки и инфекции в наружном слуховом проходе; 5. отсутствие общих противопоказаний для проведения планового хирургического вмешательства.  Рекомендована стапедопластика пациентам старше 15 лет с отосклерозом при кондуктивный или смешанный характер тугоухости с КВИ - не менее 25-30 дБ", "note": "Третье значение (25 дБ) — в разделе 6."}, "t-tech": {"s": "ok", "sec": "Приложение А3", "page": 42, "q": "В современной хирургии стремени распространенными являются две методики фенестрации его основания, при которых выполняется стапедотомия (методика малого окна, поршневая, фенестральная) или стапедэктомия (методика большого окна, полустапедэктомия или тотальная). При этом используются протезы стремени из алло-, аутотканей, различных биосовместимых материалов (тефлон (фторопласт, флюоропласт), керамика, пластипор, сталь, титан, платина и их комбинации) с сохранением сухожилия стапедиальной мышцы и наковальне-стременного сочленения и без, с изоляцией окна преддверия аутотканями (вена, жир, клетчатка, фасция) и без."}, "t-piston": {"s": "ok", "sec": "Приложение А3", "page": 43, "q": "Наибольшее распространение в мире получила поршневая методика стапедопластики, предложенная J. Shea с соавт. (1962), вследствие минимальной травмы для внутреннего уха, легкости выполнения при достаточном функциональном результате (КВИ ≤10 дБ у 58-98%)"}, "t-eff": {"s": "ok", "sec": "Приложение А3", "page": 43, "q": "Эффективными являются как стапедотомия, так и частичная стапедэктомия. Преимущество стапедэктомии (или методики большого окна) в сокращении КВИ в раннем послеоперационном периоде в сравнении с стапедотомией. Однако процент развития послеоперационной сенсоневральной тугоухости (у 3,5-5,9%), глухоты (у 0,9-2%) остается на протяжении многих лет стабильным [54]."}, "t-choice": {"s": "ok", "sec": "Приложение А3", "page": 46, "q": "Выбор методики стапедопластики должен зависить от результатов дооперационного обследования, интраоперационных находок и особенностей течения операции. На дооперационном этапе учитываются возраст пациента, жалобы, анамнез заболевания, величина порогов КП и КВИ, особенности строения височной кости по данным МСКТ височных костей. Интраоперационно необходимо учитывать распространение очагов отосклероза, их активность, анатомические особенности строения ниши окна преддверия, канала лицевого нерва, выраженность кровотечения из тканей и давление перилимфы [34, 72, 74, 75]."}, "t-choice-2": {"s": "ok", "sec": "Приложение А3", "page": 46, "q": "Поршневая методика стапедопластики показана в молодом возрасте (до 40 лет), при выявленной интраоперационно активности очагов отосклероза, узкой ниши окна преддверия и распространенных формах отосклероза, с крупными очагами на промонториуме, облитерирующих формах и повышенном кровотечении во время операции. Аутотканевая стапедопластика показана пациентам старшего возраста, особенно с длительным снижением слуха, при смешанных формах отосклероза, выявлении по данным МСКТ височных костей расширенного водопровода улитки. При невозможности выполнения аутотканевой стапедопластики выполняется стапедопластика протезом на аутовенозный трансплантат."}, "cr-young": {"s": "ok", "sec": "Приложение А3", "page": 47, "q": "Критерии выбора методики Поршневая стапедопластика Стапедопластика протезом на аутовену Стапедопластика с применением аутотканей Молодой возраст (<40 лет) + + –", "note": "Сверено по изображению страницы 47.", "img": [47]}, "cr-long": {"s": "ok", "sec": "Приложение А3", "page": 47, "q": "Критерии выбора методики Поршневая стапедопластика Стапедопластика протезом на аутовену Стапедопластика с применением аутотканей Молодой возраст (<40 лет) + + – Длительность заболевания (>10 лет) – – +", "note": "Сверено по изображению страницы 47.", "img": [47]}, "cr-mix2": {"s": "ok", "sec": "Приложение А3", "page": 47, "q": "Критерии выбора методики Поршневая стапедопластика Стапедопластика протезом на аутовену Стапедопластика с применением аутотканей Молодой возраст (<40 лет) + + – Длительность заболевания (>10 лет) – – + Отосклероз, смешанная форма II – + +", "note": "Сверено по изображению страницы 47.", "img": [47]}, "cr-active": {"s": "ok", "sec": "Приложение А3", "page": 47, "q": "Критерии выбора методики Поршневая стапедопластика Стапедопластика протезом на аутовену Стапедопластика с применением аутотканей Молодой возраст (<40 лет) + + – Длительность заболевания (>10 лет) – – + Отосклероз, смешанная форма II – + + Активный отосклероз + + –", "note": "Сверено по изображению страницы 47.", "img": [47]}, "cr-oblit": {"s": "ok", "sec": "Приложение А3", "page": 47, "q": "Критерии выбора методики Поршневая стапедопластика Стапедопластика протезом на аутовену Стапедопластика с применением аутотканей Молодой возраст (<40 лет) + + – Длительность заболевания (>10 лет) – – + Отосклероз, смешанная форма II – + + Активный отосклероз + + – Облитерирующий отосклероз + – –", "note": "Сверено по изображению страницы 47.", "img": [47]}, "cr-narrow": {"s": "ok", "sec": "Приложение А3", "page": 47, "q": "Критерии выбора методики Поршневая стапедопластика Стапедопластика протезом на аутовену Стапедопластика с применением аутотканей Молодой возраст (<40 лет) + + – Длительность заболевания (>10 лет) – – + Отосклероз, смешанная форма II – + + Активный отосклероз + + – Облитерирующий отосклероз + – – Анатомическая узкая ниша окна преддверия + + –", "note": "Сверено по изображению страницы 47.", "img": [47]}, "cr-hydr": {"s": "ok", "sec": "Приложение А3", "page": 47, "q": "Критерии выбора методики Поршневая стапедопластика Стапедопластика протезом на аутовену Стапедопластика с применением аутотканей Молодой возраст (<40 лет) + + – Длительность заболевания (>10 лет) – – + Отосклероз, смешанная форма II – + + Активный отосклероз + + – Облитерирующий отосклероз + – – Анатомическая узкая ниша окна преддверия + + – Наличие гидропса лабиринта по данным ЭКоГ + + +", "note": "Сверено по изображению страницы 47.", "img": [47]}, "cr-peri": {"s": "ok", "sec": "Приложение А3", "page": 47, "q": "Критерии выбора методики Поршневая стапедопластика Стапедопластика протезом на аутовену Стапедопластика с применением аутотканей Молодой возраст (<40 лет) + + – Длительность заболевания (>10 лет) – – + Отосклероз, смешанная форма II – + + Активный отосклероз + + – Облитерирующий отосклероз + – – Анатомическая узкая ниша окна преддверия + + – Наличие гидропса лабиринта по данным ЭКоГ + + + Расширенный водопровод улитки, дегисценция – + + верхнего ПК и гидропс лабиринта по данным ЭКоГ (перилимфатический гидропс)", "note": "Сверено по изображению страницы 47.", "img": [47]}, "cr-endo": {"s": "ok", "sec": "Приложение А3", "page": 47, "q": "Критерии выбора методики Поршневая стапедопластика Стапедопластика протезом на аутовену Стапедопластика с применением аутотканей Молодой возраст (<40 лет) + + – Длительность заболевания (>10 лет) – – + Отосклероз, смешанная форма II – + + Активный отосклероз + + – Облитерирующий отосклероз + – – Анатомическая узкая ниша окна преддверия + + – Наличие гидропса лабиринта по данным ЭКоГ + + + Расширенный водопровод улитки, дегисценция – + + верхнего ПК и гидропс лабиринта по данным ЭКоГ (перилимфатический гидропс) Расширенный водопровод преддверия и гидропс – – лабиринта по данным ЭКоГ (эндолимфатический гидропс)", "note": "Сверено по изображению страницы 47.", "img": [47]}, "t-bc": {"s": "ok", "sec": "Приложение А3", "page": 46, "q": "Отмечено, что с увеличением диаметра перфорации основания стремени и протеза при качественном выполнении уменьшаются пороги КП на 10-20 дБ по всей аудиометрической тон-шкале, чего не бывает при поршневой методике, что объясняется улучшением гидродинамики жидкостей лабиринта"}, "f7-auto": {"s": "ok", "sec": "Приложение А3, рис. 7", "page": 47, "q": "Рис. 7. Функциональные результаты различных методик стапедопластики (КВИ ≤10дБ)", "note": "Сверено по изображению страницы 47.", "img": [47]}, "f7-piston": {"s": "ok", "sec": "Приложение А3, рис. 7", "page": 47, "q": "Рис. 7. Функциональные результаты различных методик стапедопластики (КВИ ≤10дБ)", "note": "Сверено по изображению страницы 47.", "img": [47]}, "w-tbl": {"s": "ok", "sec": "Приложение А3", "page": 46, "q": "снизить риск послеоперационных кохлеовестибулярных нарушений и реоссификаций у больных отосклерозом (табл. 1)[34, 72, 75, 76]. Современные тенденции в медицине диктуют получение ранних эффективных результатов улучшения слуха и этим отличаются методики стапедопластики с изолированием жидкостей преддверия аутотканью [16, 19, 54, 76] (рис. 7). Отмечено, что с увеличением диаметра перфорации основания стремени и протеза при качественном выполнении уменьшаются пороги КП на 10-20 дБ по всей аудиометрической тон-шкале, чего не бывает при поршневой методике, что объясняется улучшением гидродинамики жидкостей лабиринта [16, 54, 77, 78, 79] (рис. 8, 9). Кроме того, при исполнении аутотканевой методики нет затрат на покупку протеза стремени. Критерии выбора методики стапедопластики у больных отосклерозом  Критерии выбора методики Поршневая стапедопластика Стапедопластика протезом на аутовену Стапедопластика с применением аутотканей Молодой возраст (<40 лет) + + – Длительность заболевания (>10 лет) – – + Отосклероз, смешанная форма II – + + Активный отосклероз + + – Облитерирующий отосклероз + – – Анатомическая узкая ниша окна преддверия + + – Наличие гидропса лабиринта по данным ЭКоГ + + + Расширенный водопровод улитки, дегисценция – + + верхнего ПК и гидропс лабиринта по данным ЭКоГ (перилимфатический гидропс) Расширенный водопровод преддверия и гидропс – – лабиринта по данным ЭКоГ (эндолимфатический гидропс)", "note": "Сверено по изображению страницы 47.", "img": [47]}, "t-ci": {"s": "ok", "sec": "3.2", "page": 25, "q": "Рекомендуется кохлеарная имплантация взрослым пациентам с отосклерозом [57, 58, 59, 60]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 4)"}, "t-ci-c": {"s": "ok", "sec": "3.2", "page": 25, "q": "рекомендуется у больных кохлеарной формой отосклероза или высоких порогах слуха после стапедопластики с двусторонней тугоухостью 4-5 степени, при разборчивости простых односложных слов <30% по данным речевой аудиометрии с оптимально подобранными слуховыми аппаратами на оба уха, при отсутствии патологии улитки по данным МСКТ и МРТ височных костей, а также достаточной мотивации пациента [60]."}, "t-ha": {"s": "ok", "sec": "3.3", "page": 25, "q": "Рекомендуется проведение электроакустической реабилитации всем пациентам с недостаточным уровнем слуха и разборчивости речи в том числе и после хирургического лечения, кохлеарной форме отосклероза, при общих противопоказаниях для хирургического лечения, отказе пациента от хирургического лечения [57]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "t-ha-c": {"s": "ok", "sec": "3.3", "page": 25, "q": "рекомендуется пациентам при уровне слуха ниже социального (пороги костной проводимости более 30 дБ или воздушной проводимости более 45 дБ в зоне речевых частот) с учётом более или менее выраженных явлений феномена ускоренного нарастания громкости (ФУНГ), присутствующих в послеоперационном периоде, так и вне его. При этом  учитываются пожелания и самого пациента в отношении самого факта слухопротезирования, в том числе и после операции, при наличии единственно слышащего уха, при общих противопоказаниях для выполнения планового хирургического лечения и в случаях отказа пациента от операции."}, "r-rehab": {"s": "ok", "sec": "4", "page": 27, "q": "рекомендуется пациентам при уровне ниже социального (пороги костной проводимости более 30 дБ или воздушной проводимости 45 и более дБ в зоне речевых частот): - после операции; - после операции, при наличии единственно слышащего уха; - при общих противопоказаниях для выполнения планового хирургического лечения, в случаях отказа пациента от операции; - при кохлеарной форме отосклероза."}, "w-45": {"s": "ok", "sec": "3.3, 4", "page": 25, "q": "воздушной проводимости более 45 дБ в зоне речевых частот) с учётом более или менее выраженных явлений феномена ускоренного нарастания громкости (ФУНГ), присутствующих в послеоперационном периоде, так и вне его. При этом  учитываются пожелания и самого пациента в отношении самого факта слухопротезирования, в том числе и после операции, при наличии единственно слышащего уха, при общих противопоказаниях для выполнения планового хирургического лечения и в случаях отказа пациента от операции.  4. Медицинская реабилитация и санаторнокурортное лечение, медицинские показания и противопоказания к применению методов медицинской реабилитации, в том числе основанных на использовании природных лечебных факторов Рекомендуется проведение электроакустической реабилитации всем пациентам с недостаточным уровнем слуха и разборчивости речи в том числе и после хирургического лечения, кохлеарной форме отосклероза, при общих противопоказаниях для хирургического лечения, отказе пациента от хирургического лечения [57]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: рекомендуется пациентам при уровне ниже социального (пороги костной проводимости более 30 дБ или воздушной проводимости 45 и более дБ"}, "p-none": {"s": "ok", "sec": "5", "page": 28, "q": "применению методов профилактики Не существует."}, "h-who": {"s": "ok", "sec": "6", "page": 29, "q": "Первичный осмотр (прием) врача-оториноларинголога. Первичный осмотр (прием) врача-сурдолога-оториноларинголога."}, "h-hosp": {"s": "ok", "sec": "6", "page": 29, "q": "Показанием к плановой госпитализации является наличие показаний к оперативному лечению: - жалобы пациента на снижение слуха и наличие субъективного ушного шума; - кондуктивный или смешанный характер тугоухости с КВИ – не менее 25 дБ; - отсутствие признаков активного отосклероза (по данным отомикроскопии и МСКТ височных костей); - отсутствие перфорации барабанной перепонки и инфекции в наружном слуховом проходе; - отсутствие общих противопоказаний для проведения планового хирургического вмешательства; - наличие необходимых обследований для проведения операций, установленных стационаром."}, "h-disch": {"s": "ok", "sec": "6", "page": 29, "q": "Выписка проводится на 7-10 день после предварительной оценки слуха по ТПА. Оценка слуховой функции с помощью ТПА: пороги по КП сохраняются без изменений в сравнении с дооперационным уровнем; КВИ в зависимости от метода операции сохраняется на прежнем уровне или сокращается (ВП уменьшаются, улучшаются)."}, "h-postop": {"s": "ok", "sec": "7", "page": 30, "q": "После операции в зависимости от методики операции рекомендуется постельный режим от 1 до 2 суток с положением на противоположном ухе. Необходимо в течение месяца беречь ухо от попадания воды и громких звуков. Противопоказаны полеты на самолете до 3 месяцев."}, "h-pt": {"s": "ok", "sec": "Приложение В", "page": 50, "q": "Положительные результаты отмечаются у девяти из десяти пациентов, прошедших данную операцию, у менее 1 % оперированных больных операция была неэффективна."}, "w-pt": {"s": "ok", "sec": "Приложение В", "page": 50, "q": "Пациенты с отосклерозом лечатся и наблюдаются врачом-сурдологом. Реабилитация тугоухости при отосклерозе проводится двумя методами: это применение слуховых аппаратов или оперативное вмешательство – стапедопластика. Оно выполняется в случае, когда имеется фиксация стремечка в овальном окне. Операция заключается в удалении ножек стремечка и замены его протезом. В подножной пластинке стремечка делается небольшое отверстие и в него вставляется тонкий протез, который работает наподобие поршня (поршневая стапедопластика), другими методиками являются, когда протез устанавливается на аутотрасплантат из вены и протез изготавливается из хряща пациента и устанавливается на трансплантат из вены. Данные операции дают хороший результат у больных, страдающих отосклерозом – нарушением подвижности слуховых косточек в среднем ухе. Положительные результаты отмечаются у девяти из десяти пациентов, прошедших данную операцию, у менее 1 % оперированных больных операция была неэффективна. Альтернативным методом слуховой реабилитации является слухопротезирование. Слуховые аппараты могут помочь эффективно справиться с нарушением слуха лишь на поздних стадиях заболевания, когда оперативное лечение не показано."}}, "terms": {}};
